CREATE OR REPLACE FUNCTION public.whatsapp_add_contact(_name text, _phone text) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE cid uuid; rid uuid; digits text; BEGIN IF auth.uid() IS NULL OR NOT EXISTS(SELECT 1 FROM public.profiles WHERE id=auth.uid() AND account_status='active') THEN RAISE EXCEPTION 'Active account required'; END IF; IF NOT (public.has_role(auth.uid(),'super_admin') OR public.messaging_allowed('whatsapp.create')) THEN RAISE EXCEPTION 'WhatsApp contact permission required'; END IF; IF length(trim(coalesce(_name,''))) NOT BETWEEN 1 AND 100 THEN RAISE EXCEPTION 'Enter a client name (1-100 characters)'; END IF; digits:=regexp_replace(coalesce(_phone,''),'\D','','g'); IF length(digits) NOT BETWEEN 8 AND 15 THEN RAISE EXCEPTION 'Enter a valid international WhatsApp number'; END IF; IF public.has_role(auth.uid(),'super_admin') THEN cid:=NULL; ELSE SELECT company_id INTO cid FROM public.company_members WHERE user_id=auth.uid() LIMIT 1; IF cid IS NULL THEN RAISE EXCEPTION 'A company membership is required'; END IF; END IF; SELECT id INTO rid FROM public.whatsapp_conversations WHERE assigned_to=auth.uid() AND wa_phone=digits LIMIT 1; IF rid IS NOT NULL THEN UPDATE public.whatsapp_conversations SET contact_name=trim(_name) WHERE id=rid; RETURN rid; END IF; INSERT INTO public.whatsapp_conversations(company_id,assigned_to,contact_name,wa_phone,unread_count) VALUES(cid,auth.uid(),trim(_name),digits,0) RETURNING id INTO rid; RETURN rid; END $$; REVOKE ALL ON FUNCTION public.whatsapp_add_contact(text,text) FROM anon; GRANT EXECUTE ON FUNCTION public.whatsapp_add_contact(text,text) TO authenticated;